CREATE TABLE "agent_runs" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "user_id" uuid NOT NULL, "surface" "agent_surface" NOT NULL, "trigger" "agent_trigger" NOT NULL, "status" "agent_run_status" DEFAULT 'running' NOT NULL, "model" text DEFAULT '' NOT NULL, "input_summary" text DEFAULT '' NOT NULL, "tool_calls" integer DEFAULT 0 NOT NULL, "tokens_in" integer DEFAULT 0 NOT NULL, "tokens_out" integer DEFAULT 0 NOT NULL, "latency_ms" integer DEFAULT 0 NOT NULL, "error" text, "created_at" timestamp with time zone DEFAULT now() NOT NULL, "finished_at" timestamp with time zone);--> statement-breakpoint
