CREATE TABLE "knowledge_items" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "user_id" uuid NOT NULL, "kind" "knowledge_kind" NOT NULL, "title" text NOT NULL, "body_md" text NOT NULL, "topic_slugs" text[] DEFAULT '{}'::text[] NOT NULL, "source" "knowledge_source" NOT NULL, "source_ref" text NOT NULL, "content_hash" text NOT NULL, "owner" "knowledge_owner" NOT NULL, "search_tsv" "tsvector" GENERATED ALWAYS AS (to_tsvector('english', coalesce(title, '') || ' ' || coalesce(body_md, ''))) STORED, "embedding" vector(384), "agent_run_id" uuid, "archived_at" timestamp with time zone, "created_at" timestamp with time zone DEFAULT now() NOT NULL, "updated_at" timestamp with time zone DEFAULT now() NOT NULL, CONSTRAINT "uq_knowledge_items_source_ref" UNIQUE("user_id","source","source_ref"));--> statement-breakpoint
CREATE TABLE "knowledge_links" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "user_id" uuid NOT NULL, "from_item_id" uuid NOT NULL, "to_type" "link_target" NOT NULL, "to_ref" text NOT NULL, "relation" "link_relation" NOT NULL, "agent_run_id" uuid, "created_at" timestamp with time zone DEFAULT now() NOT NULL, CONSTRAINT "uq_knowledge_links" UNIQUE("user_id","from_item_id","to_type","to_ref","relation"));--> statement-breakpoint
CREATE TABLE "profile_facts" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "user_id" uuid NOT NULL, "key" text NOT NULL, "value" jsonb NOT NULL, "status" "profile_fact_status" DEFAULT 'proposed' NOT NULL, "sensitivity" "fact_sensitivity" NOT NULL, "source" text NOT NULL, "confidence" real DEFAULT 0.5 NOT NULL, "verified_at" timestamp with time zone, "agent_run_id" uuid, "created_at" timestamp with time zone DEFAULT now() NOT NULL, "updated_at" timestamp with time zone DEFAULT now() NOT NULL, CONSTRAINT "uq_profile_facts_key" UNIQUE("user_id","key"));--> statement-breakpoint
